// ================================================================
// POSTEINGANG — Geschaeftspostfach <EMAIL>
// Unterschied zum Janitor: es wird NIEMALS geloescht.
// Eine Papierkorb-Regel wird zu "Archivieren" degradiert.
// ================================================================

function notionText(prop) {
  if (!prop) return '';
  if (prop.type === 'title')     return (prop.title     || []).map(t => t.plain_text).join('');
  if (prop.type === 'rich_text') return (prop.rich_text || []).map(t => t.plain_text).join('');
  if (prop.type === 'select')    return prop.select ? prop.select.name : '';
  if (prop.type === 'number')    return prop.number;
  if (prop.type === 'checkbox')  return prop.checkbox;
  return '';
}

// ---- Regeln ----------------------------------------------------
const regeln = (($('Regeln laden').first().json.results) || []).map(p => {
  const pr = p.properties || {};
  const prio = notionText(pr['Prioritaet']);
  return {
    muster:     String(notionText(pr['Muster']) || ''),
    aktion:     notionText(pr['Aktion']) || '',
    label:      notionText(pr['Label'])  || '',
    prioritaet: (prio === '' || prio === null || prio === undefined) ? 999 : Number(prio)
  };
}).filter(r => r.muster.length > 0).sort((a, b) => a.prioritaet - b.prioritaet);

// ---- Bereits protokollierte Threads ----------------------------
const bekannt = new Set(
  (($('Schon protokolliert').first().json.results) || [])
    .map(p => notionText((p.properties || {})['Thread-ID']))
    .filter(Boolean)
);

// ---- Gmail-Labels: Name -> ID ----------------------------------
const labelMap = {};
for (const it of $('Labels holen').all()) {
  const l = it.json;
  if (l && l.name && l.id) { labelMap[l.name] = l.id; }
}

function trifft(regel, mail) {
  return String(regel.muster).split(/\s+OR\s+/i).some(teil => {
    const bed = teil.trim().split(/\s+/).filter(Boolean);
    if (!bed.length) return false;
    return bed.every(b => {
      const dp = b.indexOf(':');
      if (dp < 0) return false;
      const art  = b.slice(0, dp).toLowerCase();
      const wert = b.slice(dp + 1).toLowerCase();
      if (!wert) return false;
      if (art === 'from')    return mail.von.toLowerCase().includes(wert);
      if (art === 'to')      return mail.an.toLowerCase().includes(wert);
      if (art === 'subject') return mail.betreff.toLowerCase().includes(wert);
      if (art === 'label')   return mail.labels.some(l => l.toLowerCase() === wert);
      if (art === 'is')      return mail.labels.some(l => l.toLowerCase() === wert);
      return false;
    });
  });
}

const raus = [];
const gesehen = new Set();

for (const item of $('Posteingang lesen').all()) {
  const m = item.json;

  const rohLabels = m.labelIds || m.labels || [];
  const labels = rohLabels.map(l => (typeof l === 'string' ? l : (l.id || l.name || ''))).filter(Boolean);

  const mail = {
    id:        String(m.id || ''),
    thread:    String(m.threadId || m.id || ''),
    von:       String(m.From || m.from || ''),
    an:        String(m.To   || m.to   || ''),
    betreff:   String(m.Subject || m.subject || '(kein Betreff)'),
    snippet:   String(m.snippet || '').substring(0, 400),
    datum:     m.internalDate ? new Date(Number(m.internalDate)).toISOString() : null,
    labels,
    hat_anhang: Boolean(m.attachments && m.attachments.length) || /rechnung|invoice|beleg/i.test(String(m.Subject || m.subject || '')),
    labelMap
  };

  if (bekannt.has(mail.thread)) { continue; }
  const sch = mail.von + '|' + mail.betreff;
  if (gesehen.has(sch)) { continue; }
  gesehen.add(sch);

  // Nie-anfassen-Regeln gelten nur im privaten Postfach. Hier wird
  // ohnehin nie geloescht, also soll normal klassifiziert werden.
  const treffer = regeln.find(r => r.aktion !== 'Nie anfassen' && trifft(r, mail));

  if (treffer) {
    // Im Geschaeftspostfach wird nie geloescht.
    let aktion = treffer.aktion;
    let hinweis = '';
    if (aktion === 'Papierkorb')    { aktion = 'Archivieren'; hinweis = ' [Papierkorb-Regel zu Archivieren herabgestuft]'; }
    if (aktion === 'Nie anfassen')  { aktion = 'Im Posteingang gelassen'; }

    raus.push({ json: { ...mail,
      kategorie:   'Regel',
      aktion,
      label:       treffer.label || '',
      quelle:      'Regel',
      confidence:  1,
      begruendung: 'Regel (Prio ' + treffer.prioritaet + '): ' + treffer.muster + hinweis,
      braucht_ki:  false,
      regeln_geladen: regeln.length
    }});
  } else {
    raus.push({ json: { ...mail, braucht_ki: true, regeln_geladen: regeln.length }});
  }
}

if (raus.length === 0) {
  return [{ json: { leerlauf: true, regeln_geladen: regeln.length, braucht_ki: false, aktion: null } }];
}
return raus;

const mails = $input.all().filter(it => it.json.id).map((it, i) => ({
  nr: i, id: it.json.id, thread: it.json.thread,
  von: it.json.von, an: it.json.an, betreff: it.json.betreff,
  snippet: it.json.snippet, datum: it.json.datum,
  labels: it.json.labels, hat_anhang: it.json.hat_anhang,
  labelMap: it.json.labelMap
}));
if (mails.length === 0) return [];
const kurz = mails.map(m => ({ nr: m.nr, von: m.von, an: m.an, betreff: m.betreff, snippet: m.snippet, anhang: m.hat_anhang }));
return [{ json: { anzahl: mails.length, mails, liste: JSON.stringify(kurz, null, 1) } }];

const mails = $('Paket schnueren').first().json.mails || [];

let antwort = '';
try { antwort = ($json.content && $json.content[0] && $json.content[0].text) ? $json.content[0].text : ''; } catch (e) { antwort = ''; }

let urteile = [];
if (antwort) {
  try { const t = antwort.match(/\[[\s\S]*\]/); urteile = t ? JSON.parse(t[0]) : []; } catch (e) { urteile = []; }
}

const erlaubteAktionen   = ['Eskaliert', 'Labeln', 'Archivieren', 'Im Posteingang gelassen'];
const erlaubteKategorien = ['Lead','Kunde','Eingangsrechnung','Behoerde','Recht','Tool','Bewerbung','Werbung','Sonstiges'];

return mails.map(m => {
  const u = urteile.find(x => Number(x.nr) === Number(m.nr));

  if (!u || !erlaubteAktionen.includes(u.aktion)) {
    return { json: { ...m, kategorie: 'Sonstiges', aktion: 'Im Posteingang gelassen', label: '',
      quelle: 'Unsicher', confidence: 0,
      begruendung: antwort ? 'Keine verwertbare Modellantwort' : 'Modell nicht erreichbar' } };
  }

  const conf = Number(u.confidence) || 0;
  const sicher = conf >= 0.9;
  const kategorie = erlaubteKategorien.includes(u.kategorie) ? u.kategorie : 'Sonstiges';

  // Label je Kategorie. Quartal wird aus dem Empfangsdatum vorbelegt und
  // im Rechnungs-Workflow spaeter durch das Rechnungsdatum ersetzt.
  const d = m.datum ? new Date(m.datum) : new Date();
  const q = 'Finanzen und Belege/' + d.getFullYear() + '-Q' + (Math.floor(d.getMonth() / 3) + 1);
  const labelNachKategorie = {
    'Lead': 'Leads', 'Kunde': 'Kunden', 'Eingangsrechnung': q,
    'Behoerde': 'Recht und Steuern', 'Recht': 'Recht und Steuern',
    'Tool': 'Anbieter und Zugänge', 'Bewerbung': '', 'Werbung': 'Newsletter', 'Sonstiges': ''
  };

  return { json: { ...m,
    kategorie,
    aktion:      sicher ? u.aktion : 'Im Posteingang gelassen',
    label:       labelNachKategorie[kategorie] || '',
    quelle:      sicher ? 'Claude' : 'Unsicher',
    confidence:  conf,
    begruendung: String(u.begruendung || '') + (sicher ? '' : ' [unter Schwelle 0.9]'),
    lead: kategorie === 'Lead' ? {
      firma: String(u.firma || ''), ansprechpartner: String(u.ansprechpartner || ''),
      gewerk: String(u.gewerk || ''), ort: String(u.ort || ''), anliegen: String(u.anliegen || '')
    } : null
  }};
});

// Label-Namen in IDs aufloesen. Fehlt ein Label in Gmail, wird nicht
// gelabelt und das im Log vermerkt, statt den Lauf abzubrechen.
return $input.all().map(it => {
  const j = it.json;
  const map = j.labelMap || {};
  const name = j.label || '';
  const id = name ? (map[name] || '') : '';

  return { json: {
    ...j,
    label_id: id,
    label_fehlt: Boolean(name && !id),
    begruendung: j.begruendung + (name && !id ? ' [Gmail-Label "' + name + '" existiert nicht]' : ''),
    tut_labeln:      Boolean(id),
    tut_archivieren: j.aktion === 'Archivieren'
  }};
});

