// Der Gmail-Knoten ersetzt den Datensatz durch seine eigene Antwort.
// Hier holen wir die Originalfelder ueber die Message-ID zurueck.
const orig = $('Labels aufloesen').all().map(i => i.json);
return $input.all().map(it => {
  const id = it.json.id || (it.json.error ? null : null);
  const o = orig.find(x => x.id === id);
  if (o) { return { json: o }; }
  // Fehlerfall: Item unveraendert durchreichen, damit nichts verlorengeht
  return it;
});

